<?php
declare(strict_types=1); require_once __DIR__.'/access.php'; require_role('admin');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=(string)$_POST['status'];if(in_array($status,['approved','rejected'],true))$pdo->prepare('UPDATE leave_requests SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);}$rows=$pdo->query('SELECT l.*,u.name FROM leave_requests l JOIN users u ON u.id=l.employee_id ORDER BY l.created_at DESC')->fetchAll();function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><title>Leave Requests</title><link rel="stylesheet" href="assets/css/saas.css"></head><body class="saas-body"><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><a class="saas-nav" href="admin_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav active" href="leave_requests.php">◷ <span>Leave requests</span></a><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><h1 class="saas-title">Leave Requests</h1><section class="saas-card"><table class="saas-table"><thead><tr><th>Employee</th><th>Dates</th><th>Reason</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['name'])?></td><td><?=e($row['from_date'])?> to <?=e($row['to_date'])?></td><td><?=e($row['reason'])?></td><td><?=e($row['status'])?></td><td><?php if($row['status']==='pending'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$row['id']?>"><button name="status" value="approved" class="btn-indigo">Approve</button> <button name="status" value="rejected" class="btn-outline-indigo">Reject</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section></main></div></body></html>
